async function command(commandName, args, options = {}) {
  return new Promise((resolvePromise, reject) => {
    const child = spawn(commandName, args, { stdio: ['ignore', options.capture ? 'pipe' : 'ignore', 'pipe'] });
    let stderr = '';
    let stdout = '';
    child.stdout?.on('data', (chunk) => { stdout += chunk.toString(); });
    child.stderr.on('data', (chunk) => { stderr += chunk.toString(); });
    child.on('error', reject);
    child.on('close', (code) => code === 0 ? resolvePromise({ stdout, stderr }) : reject(new Error(`${commandName} exited ${code}: ${stderr.slice(-2000)}`)));
  });
}

async function ensureDirs() { await Promise.all(Object.values(paths).map((path) => mkdir(path, { recursive: true }))); }
async function writeJson(path, value) { await mkdir(dirname(path), { recursive: true }); await writeFile(path, `${json(value)}\n`, 'utf8'); }
async function localFile(path) { try { const info = await stat(path); return info.isFile() ? path : null; } catch { return null; } }
async function firstFile(dir, predicate) { try { const names = await readdir(dir); for (const name of names) { const path = join(dir, name); if (predicate(path)) return path; } } catch {} return null; }
async function contactSheet(inputPaths, outputPath, columns, tileWidth) {
  const usable = inputPaths.filter((path) => existsSync(path)); if (!usable.length) return null;
  const gap = 8; const tileHeight = Math.round(tileWidth * 9 / 16); const rows = Math.ceil(usable.length / columns);
  const composites = [];
  for (let index = 0; index < usable.length; index += 1) composites.push({ input: await sharp(usable[index]).resize(tileWidth, tileHeight, { fit: 'cover' }).png().toBuffer(), left: (index % columns) * (tileWidth + gap), top: Math.floor(index / columns) * (tileHeight + gap) });
  await sharp({ create: { width: columns * tileWidth + (columns - 1) * gap, height: rows * tileHeight + (rows - 1) * gap, channels: 3, background: '#101b2d' } }).composite(composites).jpeg({ quality: 90 }).toFile(outputPath);
  return outputPath;
}

