function voiceText() { return scenes.map((scene) => scene.line).join(' '); }

function svgForScene(scene, index) {
  const bg = index % 3 === 0 ? '#071823' : index % 3 === 1 ? '#10252a' : '#f4ecd7';
  const ink = bg === '#f4ecd7' ? '#101b2d' : '#f7fbf5';
  const body = '#4ed7c0'; const face = '#b9f1df'; const amber = '#ffbd5b';
  const x = 150 + (index % 4) * 55; const y = 250 + (index % 3) * 8;
  const prop = scene.prop.toLowerCase().includes('browser') ? `<rect x="700" y="185" width="360" height="235" rx="24" fill="none" stroke="${amber}" stroke-width="14"/><path d="M745 250h270M745 310h220M745 370h260" stroke="${amber}" stroke-width="11" stroke-linecap="round"/>` : scene.prop.toLowerCase().includes('tower') ? `<rect x="730" y="155" width="70" height="250" fill="${amber}"/><rect x="815" y="205" width="70" height="200" fill="${amber}"/><rect x="900" y="250" width="70" height="155" fill="${amber}"/>` : `<circle cx="850" cy="285" r="110" fill="none" stroke="${amber}" stroke-width="12"/><path d="M850 175v220M740 285h220" stroke="${amber}" stroke-width="10"/>`;
  const motion = scene.action.includes('tug') || scene.action.includes('rush') ? `<path d="M610 220L690 260M610 360L690 320" stroke="#ff6f61" stroke-width="12" stroke-linecap="round"/>` : `<path d="M520 420C650 350 660 220 780 190" fill="none" stroke="${amber}" stroke-width="9" stroke-dasharray="18 14"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720"><rect width="1280" height="720" fill="${bg}"/><text x="58" y="70" fill="${ink}" font-size="28" font-family="Arial" font-weight="700">STORYBOARD ${String(index + 1).padStart(2, '0')} · ${scene.importance}</text>${prop}${motion}<g transform="translate(${x} ${y})"><path d="M40 180L0 250M170 180L210 250" stroke="#101b2d" stroke-width="16" stroke-linecap="round"/><rect x="38" y="68" width="135" height="140" rx="42" fill="${body}" stroke="#101b2d" stroke-width="12"/><circle cx="105" cy="68" r="70" fill="${face}" stroke="#101b2d" stroke-width="12"/><circle cx="78" cy="65" r="10" fill="#101b2d"/><circle cx="132" cy="65" r="10" fill="#101b2d"/><circle cx="105" cy="119" r="13" fill="${amber}"/><path d="M105 0C110-30 135-40 145-62" fill="none" stroke="${amber}" stroke-width="9" stroke-linecap="round"/><circle cx="147" cy="-65" r="12" fill="${amber}" stroke="#101b2d" stroke-width="6"/></g><text x="58" y="655" fill="${ink}" font-size="24" font-family="Arial">${scene.expression.toUpperCase()} · ${scene.action.replaceAll('&', '&amp;').slice(0, 72)}</text></svg>`;
}

async function makeStoryboard() {
  log('creating storyboard panels');
  for (let index = 0; index < scenes.length; index += 1) {
    const svg = join(paths.storyboard, `${scenes[index].id}.svg`);
    await writeFile(svg, svgForScene(scenes[index], index), 'utf8');
    await sharp(Buffer.from(await readFile(svg))).png().toFile(join(paths.storyboard, `${scenes[index].id}.png`));
  }
  await contactSheet(scenes.map((scene) => join(paths.storyboard, `${scene.id}.png`)), join(paths.storyboard, 'contact-sheet.jpg'), 4, 320);
}

async function synthesizeVoice(runtime) {
  const segments = [
    scenes.slice(0, 2), scenes.slice(2, 4), scenes.slice(4, 6), scenes.slice(6, 8), scenes.slice(8, 10), scenes.slice(10),
  ];
  const assets = []; let offset = 0; let alignment = { characters: [], characterStartTimesSeconds: [], characterEndTimesSeconds: [] };
  for (let index = 0; index < segments.length; index += 1) {
    const text = segments[index].map((scene) => scene.line).join(' ');
    log(`synthesizing voice segment ${index + 1}/${segments.length}`);
    const asset = await runtime.voice.synthesize({ text, voice: process.env.ELEVENLABS_VOICE_ID || '21m00Tcm4TlvDq8ikWAM', language: 'en' });
    const source = pathFromUri(asset.uri); if (!source) throw new Error('Voice provider returned a non-local asset URI');
    const target = join(paths.audio, `segment-${String(index + 1).padStart(2, '0')}.wav`);
    await copyFile(source, target);
    assets.push({ ...asset, sourcePath: target, text, offsetSeconds: offset });
    const segmentAlignment = asset.alignment ?? { characters: [], characterStartTimesSeconds: [], characterEndTimesSeconds: [] };
    alignment.characters.push(...segmentAlignment.characters); alignment.characterStartTimesSeconds.push(...segmentAlignment.characterStartTimesSeconds.map((value) => Number(value) + offset)); alignment.characterEndTimesSeconds.push(...segmentAlignment.characterEndTimesSeconds.map((value) => Number(value) + offset));
    offset += Number(asset.durationSeconds ?? 0);
  }
  const list = join(paths.audio, 'concat.txt'); await writeFile(list, assets.map((item) => `file '${item.sourcePath.replaceAll("'", "'\\''")}'`).join('\n'));
  const finalPath = join(paths.audio, 'final-voice.wav'); await command(ffmpeg, ['-y', '-f', 'concat', '-safe', '0', '-i', list, '-c:a', 'pcm_s16le', '-ar', '48000', '-ac', '2', finalPath]);
  const totalDuration = offset;
  return { id: `voice-${sha(alignment).slice(0, 12)}`, uri: fileUri(finalPath), mimeType: 'audio/wav', provider: assets[0].provider, model: assets[0].model, voiceId: assets[0].voiceId, durationSeconds: totalDuration, alignment, segments: assets.map((item) => ({ text: item.text, durationSeconds: item.durationSeconds, offsetSeconds: item.offsetSeconds, provider: item.provider, model: item.model, voiceId: item.voiceId, costUsd: Number(item.costUsd ?? 0) })) };
}

async function mixMusic(renderUri, musicPath, durationSeconds) {
  if (!musicPath) return renderUri;
  const renderPath = pathFromUri(renderUri); if (!renderPath) return renderUri;
  const mixed = `${renderPath}.music-${Date.now()}.mp4`;
  await command(ffmpeg, ['-y', '-i', renderPath, '-stream_loop', '-1', '-i', musicPath, '-filter_complex', '[0:a]loudnorm=I=-16:TP=-1.5:LRA=7[voice];[1:a]volume=0.13[music];[music][voice]sidechaincompress=threshold=0.025:ratio=10:attack=18:release=420[ducked];[voice][ducked]amix=inputs=2:duration=first:normalize=0,atrim=duration=' + Number(durationSeconds).toFixed(3) + ',alimiter=limit=0.95[aout]', '-map', '0:v:0', '-map', '[aout]', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-t', Number(durationSeconds).toFixed(3), '-movflags', '+faststart', mixed]);
  await copyFile(mixed, renderPath); return renderUri;
}

async function reuseExistingVoice(sourceRoot) {
  const sourceManifest = JSON.parse(await readFile(join(sourceRoot, 'animatic', 'animatic-manifest.json'), 'utf8'));
  const segmentPaths = (sourceManifest.voice?.segments ?? []).map((_, index) => join(sourceRoot, 'audio', `segment-${String(index + 1).padStart(2, '0')}.wav`));
  const finalPath = join(paths.audio, 'final-voice.wav'); const availableSegments = segmentPaths.every((path) => existsSync(path));
  if (availableSegments) { const list = join(paths.audio, 'reused-concat.txt'); await writeFile(list, segmentPaths.map((path) => `file '${path.replaceAll("'", "'\\''")}'`).join('\n')); await command(ffmpeg, ['-y', '-f', 'concat', '-safe', '0', '-i', list, '-c:a', 'pcm_s16le', '-ar', '48000', '-ac', '2', finalPath]); }
  else { const sourceVoice = pathFromUri(sourceManifest.voice?.uri); if (!sourceVoice) throw new Error('reusable voice artifact is unavailable'); await command(ffmpeg, ['-y', '-i', sourceVoice, '-c:a', 'pcm_s16le', '-ar', '48000', '-ac', '2', finalPath]); }
  return { ...sourceManifest.voice, uri: fileUri(finalPath), mimeType: 'audio/wav', provider: 'elevenlabs', model: process.env.VOICE_MODEL || 'eleven_multilingual_v2', voiceId: process.env.ELEVENLABS_VOICE_ID || '21m00Tcm4TlvDq8ikWAM' };
}

