async function evaluateScenes(runtime, finalRender, timeline, sceneAssets) {
  const reports = [];
  if (!runtime.vision) return { status: 'NOT_EVALUATED', reports: [], provider: null };
  for (const scene of timeline) {
    const asset = sceneAssets.find((item) => item.sceneId === scene.id); const path = pathFromUri(asset?.uri); if (!path) continue;
    const imageData = new Uint8Array(await readFile(path));
    const evaluation = await runtime.vision.evaluate({ imageData, mimeType: asset.mimeType || 'image/png', prompt: `Strict semantic QC for an original Klyverio CHARACTER_STORY frame. This frame must show a clear event, not a presentation. Expected narration: ${scene.line} Expected visual payoff: ${scene.visualPayoff}. Pip is the canonical recurring character: teal rounded creature, pale mint face, one amber antenna, amber core, dark navy outline. Scene importance: ${scene.importance}. Evaluate only visible evidence. Return relevanceScore, continuityScore and artifactQualityScore from 0 to 100. Check action correctness, Pip identity (silhouette, antenna, core, palette, face), readable expression, focal subject, physical causality, style consistency, unexpected text and AI artifacts. A clean original visual metaphor is acceptable; an unrelated chart, terminal, dashboard or static information card is not.` });
    const threshold = scene.importance === 'HERO' ? 78 : scene.importance === 'IMPORTANT' ? 70 : 52;
    const decision = evaluation.relevanceScore >= threshold && evaluation.continuityScore >= (scene.importance === 'HERO' ? 78 : 68) && evaluation.artifactQualityScore >= 62 ? 'KEEP' : scene.importance === 'HERO' || scene.importance === 'IMPORTANT' ? 'REGENERATE' : 'KEEP';
    reports.push({ sceneId: scene.id, importance: scene.importance, expectedMeaning: scene.visualPayoff, observedMeaning: evaluation.observedMeaning, relevanceScore: evaluation.relevanceScore, continuityScore: evaluation.continuityScore, artifactQualityScore: evaluation.artifactQualityScore, issues: evaluation.issues, decision, evaluationStatus: 'EVALUATED', provider: runtime.vision.name, model: process.env.VISION_MODEL || process.env.GEMINI_VISION_MODEL || process.env.GEMINI_TEXT_MODEL || 'gemini-3.8-flash' });
  }
  return { status: reports.length === timeline.length ? 'EVALUATED' : 'PARTIAL', reports, provider: runtime.vision.name };
}

